sksl:
uniform shader image;
uniform float2 size;
uniform float time;
uniform float origin;
uniform float angle;
uniform float start;
uniform float before;
uniform float tuneHead;
uniform float tuneTail;
float ramp(float x) {
    float a = tuneTail > 0.0 ? smoothstep(0.0, tuneTail, x) : 1.0;
    float b = tuneHead < 1.0 ? 1.0 - smoothstep(tuneHead, 1.0, x) : 1.0;
    return a * b;
}
bool arc(float2 q, float2 p, float a, float k, float du, float w, out float2 hit) {
    float2 t = float2(cos(a), sin(a));
    float2 n = float2(-t.y, t.x);
    float2 d = q - p;
    if (abs(k) * du < 0.0001) {
        hit = float2(dot(d, t), dot(d, n));
    } else {
        float r = 1.0 / k;
        float2 c = d - n * r;
        float sg = sign(k);
        hit = float2(atan(sg * dot(c, t), -sg * dot(c, n)) / abs(k), r - sg * length(c));
    }
    return hit.x >= 0.0 && hit.x < du && abs(hit.y) <= w;
}
float2 advance(float2 p, float a, float k, float du) {
    float2 t = float2(cos(a), sin(a));
    float2 n = float2(-t.y, t.x);
    if (abs(k) * du < 0.0001) return p + t * du;
    float phi = k * du;
    float2 v = -n / k;
    return p + n / k + float2(v.x * cos(phi) - v.y * sin(phi), v.x * sin(phi) + v.y * cos(phi));
}
half4 main(float2 coord) {
    float theta = radians(clamp(angle, -180.0, 180.0));
    if (abs(theta) < 0.0001) return image.eval(coord);
    float2 o = float2(size.x * 0.5, size.y);
    float2 u = float2(0.0, -1.0);
    float2 v = float2(1.0, 0.0);
    float len = size.y;
    float wide = size.x;
    if (origin < 0.5) {
        o = float2(0.0, size.y * 0.5); u = float2(1.0, 0.0); v = float2(0.0, 1.0); len = size.x; wide = size.y;
    } else if (origin < 1.5) {
        o = float2(size.x, size.y * 0.5); u = float2(-1.0, 0.0); v = float2(0.0, -1.0); len = size.x; wide = size.y;
    } else if (origin < 2.5) {
        o = float2(size.x * 0.5, 0.0); u = float2(0.0, 1.0); v = float2(-1.0, 0.0);
    }
    float2 q = float2(dot(coord - o, u), dot(coord - o, v));
    float s = clamp(start, 0.0, 1.0) * len;
    float w = wide * 0.5 + 1.0;
    float total = 0.0;
    for (int i = 0; i < 32; i++) total += ramp((float(i) + 0.5) / 32.0) / 32.0;
    float du = (len - s) / 32.0;
    float2 p = float2(s, 0.0);
    float a = 0.0;
    float2 hit;
    for (int i = 0; i < 32; i++) {
        if (du <= 0.0) break;
        float k = total > 0.0 ? theta * ramp((float(i) + 0.5) / 32.0) / (total * (len - s)) : 0.0;
        if (arc(q, p, a, k, du, w, hit)) return image.eval(o + (s + float(i) * du + hit.x) * u + hit.y * v);
        p = advance(p, a, k, du);
        a += k * du;
    }
    float side = before < 0.5 ? 0.0 : before < 1.5 ? -1.0 : 1.0;
    du = s / 32.0;
    p = float2(s, 0.0);
    a = 3.14159265;
    for (int i = 0; i < 32; i++) {
        if (du <= 0.0) break;
        float k = total > 0.0 ? side * theta * ramp((float(i) + 0.5) / 32.0) / (total * s) : 0.0;
        if (arc(q, p, a, k, du, w, hit)) return image.eval(o + (s - float(i) * du - hit.x) * u - hit.y * v);
        p = advance(p, a, k, du);
        a += k * du;
    }
    return half4(0.0);
}
